//! Replays `sender_ts_vectors.json` (outcomes of the real flag-off web
//! `embedSenderPolicy.ts`, regenerated by embedSenderVectors.test.ts) through `run_json`.
use super::run_json;
use serde_json::Value;

const VECTORS: &str = include_str!("sender_ts_vectors.json");

#[test]
fn sender_decisions_match_every_ts_generated_vector() {
    let file: Value = serde_json::from_str(VECTORS).expect("valid vectors");
    let vectors = file["vectors"].as_array().expect("vectors");
    assert!(vectors.len() > 250, "sender vector file lost coverage");
    let mut failures = Vec::new();
    for v in vectors {
        let op = v["op"].as_str().expect("op");
        let actual = run_json(op, &v["input"].to_string())
            .map(|text| serde_json::from_str::<Value>(&text).expect("answer json"));
        match actual {
            Ok(answer) if answer == v["expected"] => {}
            other => failures.push(format!(
                "{} {op}: {other:?} != {}",
                v["name"], v["expected"]
            )),
        }
    }
    assert!(
        failures.is_empty(),
        "{} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn refuses_unknown_ops_and_malformed_documents() {
    assert_eq!(
        run_json("senderNope", "{}"),
        Err("unknown_op:senderNope".into())
    );
    assert_eq!(
        run_json("senderReceipt", "{}"),
        Err("missing_field:receipt".into())
    );
    assert_eq!(
        run_json(
            "senderFailure",
            r#"{"kind":"rejected","code":1,"reason":null}"#
        ),
        Err("bad_field:code".into())
    );
    assert!(run_json("senderReceipt", "not json").is_err_and(|e| e.starts_with("bad_json:")));
}

// --- child revision (images-generate version N+1 of the same child) ---

const DIGEST: &str = "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";

fn decide(op: &str, input: &Value) -> Value {
    serde_json::from_str(&run_json(op, &input.to_string()).expect("decision")).expect("answer json")
}

/// Availability of a finished child: the server reports no revision for it.
fn child_plan(origin: Option<&str>, requested: i64, read_only: bool) -> Value {
    decide(
        "senderAvailabilityPlan",
        &serde_json::json!({
            "embed_id": "child", "parent_embed_id": "parent", "requested_version": requested,
            "read_only": read_only, "origin": origin,
            "reply": { "results": [
                { "embed_id": "child", "state": "ready" },
                { "embed_id": "parent", "state": "ready" },
            ] },
        }),
    )
}

fn child_head(version: i64) -> Value {
    serde_json::json!({
        "embed_id": "child", "hashed_chat_id": "hc", "hashed_user_id": "hu", "hashed_message_id": "hm1",
        "parent_embed_id": "parent", "version_number": version, "status": "finished", "app_id": "images",
        "skill_id": "generated_image", "hashed_task_id": "task-2", "is_private": false, "is_shared": false,
    })
}

fn child_page(version: i64) -> Value {
    serde_json::json!({
        "embed": {
            "embed_id": "child", "hashed_chat_id": "hc", "hashed_user_id": "hu", "hashed_message_id": "hm1",
            "parent_embed_id": "parent", "version_number": version, "status": "processing", "app_id": "images",
            "skill_id": "generated_image", "hashed_task_id": "task-1", "is_private": false, "is_shared": false,
            "encrypted_content": "ct-v1", "encrypted_type": "type",
        },
        "embed_keys": [],
    })
}

fn identity(head: Value, page: Value, advance: bool, digest: Option<&str>) -> Value {
    decide(
        "senderCanonicalIdentity",
        &serde_json::json!({
            "head": head, "page": page, "historical": false, "revision": null, "content_sha256": digest,
            "head_embed_ids_json": null, "embed_ids_json": "[]", "advance": advance,
        }),
    )
}

// contract-test: supporting surface=sdks.rust assertions=images-generate.revision.same-embed-new-version
#[test]
fn child_revision_head_of_a_ready_child_reads_for_an_advance() {
    assert_eq!(
        child_plan(Some("child-revision"), 2, false),
        serde_json::json!({ "outcome": "read_advance", "allow_wrapper_writes": false })
    );
    let read_current =
        serde_json::json!({ "outcome": "read_current", "allow_wrapper_writes": false });
    // Every other child write and every read-only retry keeps the equivalence-only read.
    assert_eq!(child_plan(Some("child-revision"), 2, true), read_current);
    assert_eq!(
        child_plan(Some("canonical-embed-sender"), 2, false),
        read_current
    );
    assert_eq!(child_plan(None, 2, false), read_current);
    assert_eq!(child_plan(Some("child-revision"), 1, false), read_current);
}

// contract-test: supporting surface=sdks.rust assertions=images-generate.revision.same-embed-new-version
#[test]
fn advance_identity_grants_the_next_version_under_the_canonical_precondition() {
    assert_eq!(
        identity(child_head(2), child_page(1), true, Some(DIGEST)),
        serde_json::json!({ "outcome": "advance", "precondition": { "version": 1, "ciphertext_sha256": DIGEST } })
    );
    // The head already holds N+1: the ordinary equivalence proof answers.
    let mut same_version = child_head(2);
    same_version["status"] = serde_json::json!("processing");
    same_version["hashed_task_id"] = serde_json::json!("task-1");
    assert_eq!(
        identity(same_version, child_page(2), true, Some(DIGEST)),
        serde_json::json!({ "outcome": "ok" })
    );
    // Without the advance flag an older canonical head stays a conflict.
    assert_eq!(
        identity(child_head(2), child_page(1), false, Some(DIGEST)),
        serde_json::json!({ "outcome": "conflict", "code": "embed_identity_or_version_conflict" })
    );
}

// contract-test: supporting surface=sdks.rust assertions=images-generate.revision.same-embed-new-version
#[test]
fn advance_identity_refuses_other_identities_versions_and_a_missing_digest() {
    let conflict =
        serde_json::json!({ "outcome": "conflict", "code": "embed_identity_or_version_conflict" });
    // More than one version ahead of the canonical head.
    assert_eq!(
        identity(child_head(3), child_page(1), true, Some(DIGEST)),
        conflict
    );
    for (key, value) in [
        ("hashed_message_id", serde_json::json!("hm2")),
        ("hashed_chat_id", serde_json::json!("other")),
        ("hashed_user_id", serde_json::json!("other")),
        ("parent_embed_id", serde_json::json!("other-parent")),
        ("app_id", serde_json::json!("other")),
        ("is_shared", serde_json::json!(true)),
    ] {
        let mut head = child_head(2);
        head[key] = value;
        assert_eq!(
            identity(head, child_page(1), true, Some(DIGEST)),
            conflict,
            "{key}"
        );
    }
    // A root embed never advances through this path.
    let mut root = child_head(2);
    root["parent_embed_id"] = Value::Null;
    let mut root_page = child_page(1);
    root_page["embed"]["parent_embed_id"] = Value::Null;
    assert_eq!(identity(root, root_page, true, Some(DIGEST)), conflict);
    let mut incomplete = child_page(1);
    incomplete["embed_keys_has_more_after"] = serde_json::json!(true);
    assert_eq!(
        identity(child_head(2), incomplete, true, Some(DIGEST)),
        serde_json::json!({ "outcome": "wrappers_incomplete" })
    );
    assert_eq!(
        identity(child_head(2), child_page(1), true, None),
        serde_json::json!({ "outcome": "malformed" })
    );
    assert_eq!(
        run_json(
            "senderCanonicalIdentity",
            r#"{"head":{},"historical":false,"advance":1,"page":{}}"#
        ),
        Err("bad_field:advance".into())
    );
}
